-- BigQuery View: raw.omniture
-- Source: Hive raw.omniture (acme-lake/hive/02-raw-external-tables.hql)
-- Thin projection view over omniture_logs (60-col STRING landing table).
-- Translation: direct mapping, fully-qualified table reference added.

CREATE OR REPLACE VIEW `acme-analytics.raw.omniture` AS
SELECT
    col_2  AS event_ts,
    col_8  AS ip,
    col_13 AS url,
    col_14 AS user_id,
    col_50 AS city,
    col_51 AS country,
    col_53 AS state,
    date_ts
FROM `acme-analytics.raw.omniture_logs`;

-- BigQuery View: raw.v_fraud_signals_recent
-- Source: Hive raw.v_fraud_signals_recent (acme-lake/hive/05-additional-raw-feeds.hql)
-- Translation:
--   date_format(date_sub(current_date(), 1), 'yyyyMMdd')
--     → FORMAT_DATE('%Y%m%d', DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY))

CREATE OR REPLACE VIEW `acme-analytics.raw.v_fraud_signals_recent` AS
SELECT *
FROM `acme-analytics.raw.fraud_signals`
WHERE signal_date >= FORMAT_DATE('%Y%m%d', DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY));


