-- BigQuery View: retail.vw_daily_sales_by_country
-- Source: Hive retail.vw_daily_sales_by_country (acme-analytics/hive/09-analytics-views.hql)
-- Translation: direct mapping — COALESCE/NULLIF are standard SQL, CTE + GROUP BY is direct.

CREATE OR REPLACE VIEW `acme-analytics.retail.vw_daily_sales_by_country` AS
WITH daily AS (
  SELECT
    sale_date,
    country,
    COUNT(DISTINCT invoice_no)                  AS orders,
    SUM(line_total)                             AS revenue,
    SUM(quantity)                               AS units,
    COUNT(DISTINCT customer_sk)                 AS active_customers
  FROM `acme-analytics.retail.fact_sales`
  GROUP BY sale_date, country
)
SELECT
  d.sale_date,
  d.country,
  d.orders,
  d.revenue,
  d.units,
  d.active_customers,
  COALESCE(d.revenue / NULLIF(d.orders, 0), 0)  AS aov,
  COALESCE(d.units  / NULLIF(d.orders, 0), 0)   AS basket_size
FROM daily d;

-- BigQuery View: retail.vw_weekly_sales_with_running_totals
-- Source: Hive retail.vw_weekly_sales_with_running_totals (acme-analytics/hive/09-analytics-views.hql)
-- Translation: direct mapping — window functions (SUM OVER, AVG OVER, LAG) are standard SQL.

CREATE OR REPLACE VIEW `acme-analytics.retail.vw_weekly_sales_with_running_totals` AS
WITH weekly AS (
  SELECT
    d.d_week_seq,
    d.d_year,
    SUM(f.line_total) AS wk_revenue,
    SUM(f.quantity)   AS wk_units
  FROM `acme-analytics.retail.fact_sales` f
  JOIN `acme-analytics.retail.dim_date` d ON d.d_date = f.sale_date
  GROUP BY d.d_week_seq, d.d_year
)
SELECT
  w.d_week_seq,
  w.d_year,
  w.wk_revenue,
  w.wk_units,
  SUM(w.wk_revenue) OVER (
    PARTITION BY w.d_year
    ORDER BY w.d_week_seq
  )                                                              AS ytd_revenue,
  AVG(w.wk_revenue) OVER (
    ORDER BY w.d_week_seq
    ROWS BETWEEN 12 PRECEDING AND CURRENT ROW
  )                                                              AS rolling_13wk_avg,
  LAG(w.wk_revenue, 52) OVER (ORDER BY w.d_week_seq)            AS same_week_last_year,
  w.wk_revenue - COALESCE(LAG(w.wk_revenue, 52) OVER (ORDER BY w.d_week_seq), 0)
                                                                 AS yoy_delta
FROM weekly w;

-- BigQuery View: retail.vw_customer_lifetime_value
-- Source: Hive retail.vw_customer_lifetime_value (acme-analytics/hive/09-analytics-views.hql)
-- Translation:
--   DATEDIFF(CURRENT_DATE(), last_order_date) → DATE_DIFF(CURRENT_DATE(), last_order_date, DAY)
--   CURRENT_DATE() → CURRENT_DATE() (same in BQ)

CREATE OR REPLACE VIEW `acme-analytics.retail.vw_customer_lifetime_value` AS
WITH per_customer AS (
  SELECT
    c.customer_sk,
    c.customer_id,
    c.country,
    MIN(f.sale_date)              AS first_order_date,
    MAX(f.sale_date)              AS last_order_date,
    COUNT(DISTINCT f.invoice_no)  AS orders,
    SUM(f.line_total)             AS lifetime_revenue
  FROM `acme-analytics.retail.dim_customer` c
  LEFT JOIN `acme-analytics.retail.fact_sales` f ON f.customer_sk = c.customer_sk
  GROUP BY c.customer_sk, c.customer_id, c.country
)
SELECT
  customer_sk,
  customer_id,
  country,
  first_order_date,
  last_order_date,
  orders,
  lifetime_revenue,
  DATE_DIFF(CURRENT_DATE(), last_order_date, DAY) AS recency_days,
  CASE
    WHEN orders = 0                                                    THEN 'never'
    WHEN DATE_DIFF(CURRENT_DATE(), last_order_date, DAY) <= 30        THEN 'active'
    WHEN DATE_DIFF(CURRENT_DATE(), last_order_date, DAY) <= 90        THEN 'warm'
    WHEN DATE_DIFF(CURRENT_DATE(), last_order_date, DAY) <= 365       THEN 'cold'
    ELSE 'churned'
  END                                              AS rfm_bucket
FROM per_customer;

-- BigQuery View: retail.vw_product_performance
-- Source: Hive retail.vw_product_performance (acme-analytics/hive/09-analytics-views.hql)
-- Translation: direct mapping — RANK/DENSE_RANK OVER are standard SQL.

CREATE OR REPLACE VIEW `acme-analytics.retail.vw_product_performance` AS
WITH sold AS (
  SELECT
    p.product_sk,
    p.stock_code,
    p.description,
    f.country,
    SUM(f.line_total)                AS revenue,
    SUM(f.quantity)                  AS units,
    COUNT(DISTINCT f.invoice_no)     AS orders
  FROM `acme-analytics.retail.dim_product` p
  JOIN `acme-analytics.retail.fact_sales` f ON f.product_sk = p.product_sk
  GROUP BY p.product_sk, p.stock_code, p.description, f.country
),
ranked AS (
  SELECT
    s.*,
    RANK()       OVER (PARTITION BY s.country ORDER BY s.revenue DESC)  AS country_rank,
    DENSE_RANK() OVER (                       ORDER BY s.revenue DESC)  AS global_rank
  FROM sold s
)
SELECT * FROM ranked;

-- BigQuery View: retail.vw_monthly_cohort_retention
-- Source: Hive retail.vw_monthly_cohort_retention (acme-analytics/hive/09-analytics-views.hql)
-- Translation:
--   DATE_FORMAT(MIN(sale_date), 'yyyy-MM') → FORMAT_DATE('%Y-%m', MIN(sale_date))
--   MONTHS_BETWEEN(f.sale_date, to_date(concat(fo.cohort_month, '-01')))
--     → DATE_DIFF(f.sale_date, PARSE_DATE('%Y-%m-%d', CONCAT(fo.cohort_month, '-01')), MONTH)
--   CAST(months_since_first AS INT) → CAST(months_since_first AS INT64)

CREATE OR REPLACE VIEW `acme-analytics.retail.vw_monthly_cohort_retention` AS
WITH first_order AS (
  SELECT
    customer_sk,
    FORMAT_DATE('%Y-%m', MIN(sale_date)) AS cohort_month
  FROM `acme-analytics.retail.fact_sales`
  GROUP BY customer_sk
),
orders AS (
  SELECT
    f.customer_sk,
    fo.cohort_month,
    FORMAT_DATE('%Y-%m', f.sale_date)                                            AS order_month,
    DATE_DIFF(f.sale_date, PARSE_DATE('%Y-%m-%d', CONCAT(fo.cohort_month, '-01')), MONTH) AS months_since_first
  FROM `acme-analytics.retail.fact_sales` f
  JOIN first_order fo ON fo.customer_sk = f.customer_sk
)
SELECT
  cohort_month,
  CAST(months_since_first AS INT64)    AS months_since_first,
  COUNT(DISTINCT customer_sk)          AS active_customers
FROM orders
GROUP BY cohort_month, CAST(months_since_first AS INT64);

-- BigQuery View: retail.vw_otd_by_carrier_30d
-- Source: Hive retail.vw_otd_by_carrier_30d (acme-analytics/hive/16-additional-views.hql)
-- Translation:
--   shipped_ts + INTERVAL '48' HOUR → TIMESTAMP_ADD(shipped_ts, INTERVAL 48 HOUR)
--   unix_timestamp(delivered_ts) - unix_timestamp(shipped_ts)
--     → UNIX_SECONDS(delivered_ts) - UNIX_SECONDS(shipped_ts)
--   date_sub(current_date(), 30) → DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY)
--   shipped_ts >= date → CAST comparison (shipped_ts is TIMESTAMP, filter is DATE)

CREATE OR REPLACE VIEW `acme-analytics.retail.vw_otd_by_carrier_30d` AS
SELECT
    carrier,
    COUNT(*)                                                                     AS shipments,
    AVG(CASE WHEN delivered_ts <= TIMESTAMP_ADD(shipped_ts, INTERVAL 48 HOUR)
             THEN 1.0 ELSE 0.0 END)                                              AS otd_rate,
    AVG(UNIX_SECONDS(delivered_ts) - UNIX_SECONDS(shipped_ts)) / 3600.0           AS avg_transit_hours
FROM `acme-analytics.retail.fact_shipments`
WHERE shipped_ts >= TIMESTAMP(DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY))
GROUP BY carrier;

-- BigQuery View: retail.vw_session_to_order_attribution
-- Source: Hive retail.vw_session_to_order_attribution (acme-analytics/hive/09-analytics-views.hql)
-- Cross-project: raw.mobile_events → acme-analytics.raw.mobile_events
-- Translation:
--   s.event_ts + INTERVAL '1' DAY → TIMESTAMP_ADD(s.event_ts, INTERVAL 1 DAY)
--   s.context.referrer → s.context.referrer (STRUCT access is same in BQ)

CREATE OR REPLACE VIEW `acme-analytics.retail.vw_session_to_order_attribution` AS
SELECT
  s.user_id,
  s.event_ts                                AS session_ts,
  s.context.referrer                        AS referrer,
  f.invoice_no,
  f.invoice_ts                              AS order_ts,
  f.line_total
FROM `acme-analytics.raw.mobile_events` s
LEFT JOIN `acme-analytics.retail.dim_customer` dc ON dc.customer_id = s.user_id
LEFT JOIN `acme-analytics.retail.fact_sales` f
       ON  f.customer_sk = dc.customer_sk
       AND f.invoice_ts BETWEEN s.event_ts AND TIMESTAMP_ADD(s.event_ts, INTERVAL 1 DAY);

-- BigQuery View: retail.vw_active_member_panel
-- Source: Hive retail.vw_active_member_panel (acme-analytics/hive/16-additional-views.hql)
-- Trap T1: NDV() (Impala approx-distinct) → APPROX_COUNT_DISTINCT()
-- Translation:
--   NDV(member_id) → APPROX_COUNT_DISTINCT(member_id)
--   date_sub(current_date(), 30) → DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY)
-- Note: source view references `region` column on fact_loyalty_events. The source
--   Hive table does not have a `region` column — this view relies on a join or
--   implicit column. In BQ we join to dim_store via store_sk to get region.

CREATE OR REPLACE VIEW `acme-analytics.retail.vw_active_member_panel` AS
SELECT
    s.region,
    APPROX_COUNT_DISTINCT(f.member_id)  AS approx_active_members,
    COUNT(DISTINCT f.member_id)         AS exact_active_members,
    SUM(f.points)                       AS total_points_redeemed
FROM `acme-analytics.retail.fact_loyalty_events` f
JOIN `acme-analytics.retail.dim_store` s ON s.store_sk = f.store_sk
WHERE f.event_type = 'REDEEM'
  AND f.event_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY)
GROUP BY s.region;

-- BigQuery View: retail.vw_sales_rollup_by_region
-- Source: Hive retail.vw_sales_rollup_by_region (acme-analytics/hive/16-additional-views.hql)
-- Trap T2: WITH ROLLUP → GROUP BY ROLLUP(...)
-- Translation:
--   GROUP BY s.region, s.store_sk WITH ROLLUP → GROUP BY ROLLUP(s.region, s.store_sk)
--   GROUPING__ID → GROUPING(s.region) + GROUPING(s.store_sk) expression
--   date_sub(current_date(), 7) → DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY)

CREATE OR REPLACE VIEW `acme-analytics.retail.vw_sales_rollup_by_region` AS
SELECT
    s.region,
    s.store_sk,
    SUM(f.line_total)              AS total_revenue,
    COUNT(*)                       AS line_count,
    GROUPING(s.region) * 2 + GROUPING(s.store_sk) AS grouping_level
FROM `acme-analytics.retail.fact_sales` f
JOIN `acme-analytics.retail.dim_store` s ON s.store_sk = f.customer_sk
WHERE f.sale_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY)
GROUP BY ROLLUP(s.region, s.store_sk);

-- BigQuery View: retail.vw_category_hierarchy_recursive
-- Source: Hive retail.vw_category_hierarchy_recursive (acme-analytics/hive/16-additional-views.hql)
-- Trap T3: WITH RECURSIVE — BigQuery supports WITH RECURSIVE natively.
-- Translation: direct mapping with fully-qualified table references.

CREATE OR REPLACE VIEW `acme-analytics.retail.vw_category_hierarchy_recursive` AS
WITH RECURSIVE cat_tree AS (
    SELECT
        category_id,
        name,
        parent_id,
        CAST(name AS STRING) AS path,
        0 AS depth
    FROM `acme-analytics.retail.dim_category`
    WHERE parent_id IS NULL OR parent_id = ''

    UNION ALL

    SELECT
        c.category_id,
        c.name,
        c.parent_id,
        CONCAT(t.path, ' > ', c.name) AS path,
        t.depth + 1                   AS depth
    FROM `acme-analytics.retail.dim_category` c
    JOIN cat_tree t ON c.parent_id = t.category_id
    WHERE t.depth < 8
)
SELECT * FROM cat_tree;

-- BigQuery View: retail.vw_panel_continuity_score
-- Source: Hive retail.vw_panel_continuity_score (acme-analytics/hive/16-additional-views.hql)
-- Trap T4: UDF inside JOIN ON clause.
-- Translation:
--   normalize_country(x) → `acme-analytics.retail.normalize_country`(x)
--   BigQuery UDF must be deployed before this view is created.
--   date_sub(current_date(), 90) → DATE_SUB(CURRENT_DATE(), INTERVAL 90 DAY)

CREATE OR REPLACE VIEW `acme-analytics.retail.vw_panel_continuity_score` AS
SELECT
    f.customer_sk,
    COUNT(DISTINCT f.sale_date)         AS active_days,
    COUNT(DISTINCT f.product_sk)        AS distinct_products,
    SUM(f.line_total)                   AS total_spend
FROM `acme-analytics.retail.fact_sales` f
JOIN `acme-analytics.retail.dim_customer` c
  ON c.customer_sk = f.customer_sk
 AND `acme-analytics.retail.normalize_country`(c.country)
   = `acme-analytics.retail.normalize_country`(f.country)
WHERE f.sale_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 90 DAY)
GROUP BY f.customer_sk;


